// --- Component Schema ---


export type TechConnectorsProps = Record<string, any>;

const TechConnectors: React.FC<TechConnectorsProps> = ({
  backgroundColor = "#f3f4f6",
  transparentBackground = false,
  accentColor = "#3B82F6",
  connectorColor = "#3B82F6",
  durationInSeconds = 5,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // --- Layout Configuration ---
  const iconSize = 180; // Increased size
  const targetIconSize = 150; // Increased size
  
  const sourcePos = { x: width * 0.33, y: height * 0.5 }; // Moved closer to center
  
  const spacing = 300; // Increased spacing for larger icons
  const targetX = width * 0.67; // Moved closer to center
  const targets = [
    { id: "calendar", x: targetX, y: height * 0.5 - spacing, Icon: CalendarIcon, delay: 0 },
    { id: "onedrive", x: targetX, y: height * 0.5, Icon: OneDriveIcon, delay: 10 },
    { id: "slack", x: targetX, y: height * 0.5 + spacing, Icon: SlackIcon, delay: 20 },
  ];

  // --- Animation Helper ---
  const calculateAnimations = (startFrame: number) => {
    // Line Drawing (Reveal)
    const lineProgress = interpolate(
      frame,
      [startFrame, startFrame + 25],
      [0, 1],
      { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
    );

    // Icon Pop
    const iconSpring = spring({
      fps,
      frame: frame - (startFrame + 20),
      config: { damping: 12, stiffness: 100 },
      durationInFrames: 30,
    });

    return { lineProgress, iconSpring };
  };

  // --- Pulse & Movement Logic ---
  const startOffset = 15;
  // Gentle pulse calculation: Base 1 + sine wave
  const pulseScale = 1 + 0.05 * Math.sin(frame / 8); 
  // Entrance spring for main icon
  const sourceEntrance = spring({ 
    fps, 
    frame, 
    config: { damping: 10 } 
  });
  // Combine entrance with pulse
  const finalSourceScale = sourceEntrance * pulseScale;

  // Dash animation for "information moving"
  // Negative offset moves dash pattern "forward" along path
  const movingDashOffset = -frame * 5;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter" }}>
      
      {/* --- Connectors Layer (SVG) --- */}
      <svg
        style={{
          position: "absolute",
          width: width,
          height: height,
          overflow: "visible",
          pointerEvents: "none",
        }}
      >
        <defs>
          {targets.map((t) => {
            const maskId = `mask-${t.id}`;
            const anim = calculateAnimations(startOffset + t.delay);
            
            const cp1x = sourcePos.x + (t.x - sourcePos.x) * 0.5;
            const cp1y = sourcePos.y;
            const cp2x = sourcePos.x + (t.x - sourcePos.x) * 0.5;
            const cp2y = t.y;
            const pathData = `M ${sourcePos.x} ${sourcePos.y} C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${t.x} ${t.y}`;
            
            const len = Math.hypot(t.x - sourcePos.x, t.y - sourcePos.y) * 1.5;

            return (
              <React.Fragment key={t.id}>
                {/* Added maskUnits="userSpaceOnUse" to fix potential missing mask on straight lines */}
                <mask id={maskId} maskUnits="userSpaceOnUse">
                  <path
                    d={pathData}
                    stroke="white"
                    strokeWidth="24"
                    fill="none"
                    strokeDasharray={len}
                    strokeDashoffset={len * (1 - anim.lineProgress)}
                    strokeLinecap="round"
                  />
                </mask>
              </React.Fragment>
            );
          })}
        </defs>

        {/* --- Background Grey Lines (The "Existing" Track) --- */}
        {targets.map((t) => {
           const cp1x = sourcePos.x + (t.x - sourcePos.x) * 0.5;
           const cp1y = sourcePos.y;
           const cp2x = sourcePos.x + (t.x - sourcePos.x) * 0.5;
           const cp2y = t.y;
           const pathData = `M ${sourcePos.x} ${sourcePos.y} C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${t.x} ${t.y}`;
           
           return (
            <path
              key={`bg-${t.id}`}
              d={pathData}
              stroke="#d1d5db" 
              strokeWidth="7"
              fill="none"
              strokeDasharray="16 16" 
              strokeLinecap="round"
            />
          );
        })}

        {/* --- Foreground Colored Lines (The animated fill with moving dashes) --- */}
        {targets.map((t) => {
           const cp1x = sourcePos.x + (t.x - sourcePos.x) * 0.5;
           const cp1y = sourcePos.y;
           const cp2x = sourcePos.x + (t.x - sourcePos.x) * 0.5;
           const cp2y = t.y;
           const pathData = `M ${sourcePos.x} ${sourcePos.y} C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${t.x} ${t.y}`;
           
           return (
            <path
              key={t.id}
              d={pathData}
              stroke={connectorColor}
              strokeWidth="7"
              fill="none"
              mask={`url(#mask-${t.id})`}
              strokeDasharray="16 16" 
              strokeDashoffset={movingDashOffset} 
              strokeLinecap="round"
            />
          );
        })}
      </svg>

      {/* --- Source Icon (Lightning) --- */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          zIndex: 10,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: sourcePos.x - iconSize / 2,
            top: sourcePos.y - iconSize / 2,
            width: iconSize,
            height: iconSize,
            backgroundColor: accentColor,
            borderRadius: iconSize * 0.25,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            boxShadow: "0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04)",
            transform: `scale(${finalSourceScale})`,
          }}
        >
           <LightningIcon size={iconSize * 0.6} color="white" />
        </div>
      </AbsoluteFill>

      {/* --- Target Icons --- */}
      {targets.map((t) => {
        const anim = calculateAnimations(startOffset + t.delay);
        const scale = anim.iconSpring;
        const opacity = interpolate(scale, [0, 0.5], [0, 1], { extrapolateRight: "clamp" });

        return (
          <div
            key={t.id}
            style={{
              position: "absolute",
              left: t.x - targetIconSize / 2,
              top: t.y - targetIconSize / 2,
              width: targetIconSize,
              height: targetIconSize,
              backgroundColor: "white",
              borderRadius: "50%",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              boxShadow: "0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05)",
              transform: `scale(${scale})`,
              opacity,
              zIndex: 10,
            }}
          >
            <t.Icon size={targetIconSize * 0.6} />
          </div>
        );
      })}

    </AbsoluteFill>
  );
};

export default TechConnectors;